//! Known-answer vectors in `vectors/proto/`, generated by an encoder written independently of
//! this crate. Each success case is checked in both directions; each failure case must be
//! rejected with the named error variant.

use core::fmt::Debug;
use core::time::Duration;

use pingers_proto::{
    AppMessage, BoardBeacon, BoardCursor, BoardPage, ChatBody, ChatMessageId, Delivery,
    E7Coordinate, Epoch, HeadingDegrees, KeyConfigHash, KeyPackageBytes, Knock, KnockSignature,
    Lamport, LeafIndex, Lease, LocationGeneration, LocationPlaintext, MailboxId, MailboxSpec,
    MeetPoint, MeetPointLabel, MeetupHint, MeetupMessage, MlsMessageBytes, ProtoError, PushBind,
    PushClass, PushHandle, PushPlatform, PushRelayConfig, PushRelayKeyConfig, PushRelayKeyId,
    PushRequest, PushToken, PushTokenPlaintext, Record, RecordRandomness, RecordTag, RelayId,
    RelayRef, RelayUrl, RevokeCommitment, RlnAuth, RlnScope, SealedBeacon, SealedLocationFrame,
    SealedPush, SealedPushBlob, SeenSegment, SegmentHash, SegmentInfo, Subscription,
    SubscriptionId, TimeToLive, Urgency, WireDecode, WireEncode,
};
use pingers_testkit::{Vector, VectorError, load_vectors};
use pingers_time::{Bucket, UnixSeconds};

#[derive(Debug, thiserror::Error)]
enum TestError {
    #[error(transparent)]
    Vector(#[from] VectorError),
    #[error(transparent)]
    Proto(#[from] ProtoError),
    #[error("vector `{vector}` field `{field}` is missing or has the wrong type")]
    Field { vector: String, field: &'static str },
}

fn field_error(vector: &Vector, field: &'static str) -> TestError {
    TestError::Field {
        vector: vector.name.clone(),
        field,
    }
}

fn bytes<const LENGTH: usize>(
    vector: &Vector,
    field: &'static str,
) -> Result<[u8; LENGTH], TestError> {
    vector
        .input_bytes(field)?
        .try_into()
        .map_err(|_length| field_error(vector, field))
}

/// An optional bytes field: `""` means absent.
fn optional_bytes<const LENGTH: usize>(
    vector: &Vector,
    field: &'static str,
) -> Result<Option<[u8; LENGTH]>, TestError> {
    if vector.input_bytes(field)?.is_empty() {
        Ok(None)
    } else {
        bytes(vector, field).map(Some)
    }
}

fn number(vector: &Vector, field: &'static str) -> Result<u64, TestError> {
    Ok(vector.input_u64(field)?)
}

fn small<T: TryFrom<u64>>(vector: &Vector, field: &'static str) -> Result<T, TestError> {
    T::try_from(number(vector, field)?).map_err(|_overflow| field_error(vector, field))
}

fn signed(vector: &Vector, field: &'static str) -> Result<i32, TestError> {
    vector
        .inputs
        .get(field)
        .and_then(serde_json::Value::as_i64)
        .and_then(|value| i32::try_from(value).ok())
        .ok_or_else(|| field_error(vector, field))
}

fn text(vector: &Vector, field: &'static str) -> Result<String, TestError> {
    vector
        .inputs
        .get(field)
        .and_then(serde_json::Value::as_str)
        .map(str::to_owned)
        .ok_or_else(|| field_error(vector, field))
}

fn bucket(vector: &Vector, field: &'static str) -> Result<Bucket, TestError> {
    Bucket::from_index(number(vector, field)?)
        .map_err(ProtoError::Bucket)
        .map_err(TestError::from)
}

/// The variant name of an error, as vector files spell it.
fn variant_name(error: &ProtoError) -> String {
    let printed = format!("{error:?}");
    printed
        .split(|character: char| !character.is_alphanumeric())
        .next()
        .unwrap_or_default()
        .to_owned()
}

/// How one vector file is read: the bytes field name and the type's three operations.
struct Format<T> {
    file: &'static str,
    bytes_field: &'static str,
    build: fn(&Vector) -> Result<T, TestError>,
    encode: fn(&T) -> Result<Vec<u8>, ProtoError>,
    decode: fn(&[u8]) -> Result<T, ProtoError>,
}

fn check<T: PartialEq + Debug>(format: &Format<T>) -> Result<(), TestError> {
    let file = load_vectors(&format!("proto/{}", format.file))?;
    assert!(!file.vectors.is_empty(), "{} has no vectors", format.file);
    for vector in &file.vectors {
        if let Some(expected_error) = vector.expected.get("error") {
            let bytes = vector.input_bytes(format.bytes_field)?;
            let error = (format.decode)(&bytes).err();
            assert_eq!(
                error.as_ref().map(variant_name).as_deref(),
                expected_error.as_str(),
                "{}",
                vector.name
            );
            continue;
        }
        let bytes = vector.expected_bytes(format.bytes_field)?;
        let value = (format.build)(vector)?;
        assert_eq!((format.encode)(&value)?, bytes, "{}: encode", vector.name);
        assert_eq!((format.decode)(&bytes)?, value, "{}: decode", vector.name);
    }
    Ok(())
}

#[test]
fn record_vectors() -> Result<(), TestError> {
    check(&Format {
        file: "record-encoding",
        bytes_field: "record",
        build: |vector| {
            Ok(Record {
                randomness: RecordRandomness::from_bytes(bytes(vector, "randomness")?),
                tag: RecordTag::from_bytes(bytes(vector, "tag")?),
                sealed: SealedBeacon::from_bytes(bytes(vector, "sealed")?),
            })
        },
        encode: |record| Ok(record.to_bytes().to_vec()),
        decode: |bytes| {
            let fixed: &[u8; Record::SIZE] =
                bytes
                    .try_into()
                    .map_err(|_length| ProtoError::WrongLength {
                        expected: Record::SIZE,
                        actual: bytes.len(),
                    })?;
            Ok(Record::from_bytes(fixed))
        },
    })
}

#[test]
fn lease_vectors() -> Result<(), TestError> {
    check(&Format {
        file: "lease-encoding",
        bytes_field: "lease",
        build: |vector| {
            let records = Record::parse_concatenated(&vector.input_bytes("records")?)?;
            Ok(Lease {
                start: bucket(vector, "start_bucket")?,
                records: records
                    .try_into()
                    .map_err(|_count| field_error(vector, "records"))?,
                revoke_commitment: RevokeCommitment::from_bytes(bytes(
                    vector,
                    "revoke_commitment",
                )?),
            })
        },
        encode: |lease| Ok(lease.to_bytes().to_vec()),
        decode: Lease::from_bytes,
    })
}

