#[test]
fn push_token_plaintext_vectors() -> Result<(), TestError> {
    check(&Format {
        file: "push-token-plaintext",
        bytes_field: "padded",
        build: |vector| {
            let platform = match text(vector, "platform")?.as_str() {
                "fcm" => PushPlatform::Fcm,
                "unified_push" => PushPlatform::UnifiedPush,
                _ => return Err(field_error(vector, "platform")),
            };
            let class = match text(vector, "class")?.as_str() {
                "standard" => PushClass::Standard,
                "location" => PushClass::Location,
                _ => return Err(field_error(vector, "class")),
            };
            Ok(PushTokenPlaintext {
                platform,
                class,
                token: PushToken::from_bytes(vector.input_bytes("token")?),
                not_after: UnixSeconds::new(number(vector, "not_after")?),
            })
        },
        encode: |plaintext| plaintext.encode_padded().map(|bytes| bytes.to_vec()),
        decode: |bytes| {
            let fixed: &[u8; PushTokenPlaintext::PADDED_SIZE] =
                bytes
                    .try_into()
                    .map_err(|_length| ProtoError::WrongLength {
                        expected: PushTokenPlaintext::PADDED_SIZE,
                        actual: bytes.len(),
                    })?;
            PushTokenPlaintext::decode_padded(fixed)
        },
    })
}

fn meetup_message(vector: &Vector) -> Result<MeetupMessage, TestError> {
    Ok(match text(vector, "kind")?.as_str() {
        "keep_alive" => MeetupMessage::KeepAlive,
        "chat" => MeetupMessage::Chat {
            id: ChatMessageId::from_bytes(bytes(vector, "id")?),
            parent: optional_bytes(vector, "parent")?.map(ChatMessageId::from_bytes),
            body: ChatBody::new(text(vector, "body")?)?,
            written_at: UnixSeconds::new(number(vector, "written_at")?),
        },
        "sealed_location" => MeetupMessage::SealedLocation(SealedLocationFrame {
            generation: LocationGeneration::new(small(vector, "generation")?),
            nonce: bytes(vector, "nonce")?,
            ciphertext: vector.input_bytes("ciphertext")?,
        }),
        "meet_point_fixed" => MeetupMessage::MeetPoint(MeetPoint::Fixed {
            position: E7Coordinate::new(signed(vector, "latitude")?, signed(vector, "longitude")?)?,
            label: Some(MeetPointLabel::new(text(vector, "label")?)?),
            lamport: Lamport::new(number(vector, "lamport")?),
        }),
        "meet_point_at_member" => MeetupMessage::MeetPoint(MeetPoint::AtMember {
            leaf: LeafIndex::new(small(vector, "leaf")?),
            lamport: Lamport::new(number(vector, "lamport")?),
        }),
        "board_seen" => MeetupMessage::BoardSeen {
            segments: vec![SeenSegment {
                start: bucket(vector, "start_bucket")?,
                hash: SegmentHash::from_bytes(bytes(vector, "hash")?),
            }],
        },
        _ => return Err(field_error(vector, "kind")),
    })
}

#[test]
fn meetup_message_vectors() -> Result<(), TestError> {
    check(&Format {
        file: "meetup-message-encoding",
        bytes_field: "encoding",
        build: meetup_message,
        encode: MeetupMessage::encode,
        decode: MeetupMessage::decode,
    })
}

#[test]
fn location_plaintext_vectors() -> Result<(), TestError> {
    check(&Format {
        file: "location-plaintext-encoding",
        bytes_field: "encoding",
        build: |vector| {
            let speed_given = vector
                .inputs
                .get("speed")
                .is_some_and(|value| value.as_u64().is_some());
            Ok(LocationPlaintext {
                position: E7Coordinate::new(
                    signed(vector, "latitude")?,
                    signed(vector, "longitude")?,
                )?,
                accuracy: pingers_proto::AccuracyMeters::new(small(vector, "accuracy")?),
                heading: Some(HeadingDegrees::new(small(vector, "heading")?)?),
                speed: if speed_given {
                    Some(pingers_proto::SpeedCentimetresPerSecond::new(small(
                        vector, "speed",
                    )?))
                } else {
                    None
                },
                taken_at: UnixSeconds::new(number(vector, "taken_at")?),
            })
        },
        encode: LocationPlaintext::encode,
        decode: LocationPlaintext::decode,
    })
}

fn urgency(vector: &Vector, field: &'static str) -> Result<Urgency, TestError> {
    match text(vector, field)?.as_str() {
        "alert" => Ok(Urgency::Alert),
        "quiet" => Ok(Urgency::Quiet),
        _ => Err(field_error(vector, field)),
    }
}

fn sealed_push(vector: &Vector) -> Result<SealedPush, TestError> {
    let relay = if text(vector, "relay_url").is_ok_and(|url| !url.is_empty()) {
        RelayRef::Custom {
            url: RelayUrl::new(text(vector, "relay_url")?)?,
            key_config_hash: KeyConfigHash::from_bytes(bytes(vector, "key_config_hash")?),
        }
    } else {
        RelayRef::Listed(RelayId::new(small(vector, "relay_id")?))
    };
    Ok(SealedPush {
        relay,
        blob: SealedPushBlob::from_bytes(bytes(vector, "blob")?),
        urgency: urgency(vector, "urgency")?,
        handle: PushHandle::from_bytes(bytes(vector, "handle")?),
    })
}

fn time_to_live(vector: &Vector, field: &'static str) -> Result<TimeToLive, TestError> {
    Ok(TimeToLive::new(Duration::from_secs(number(
        vector, field,
    )?))?)
}

