#[test]
fn knock_vectors() -> Result<(), TestError> {
    check(&Format {
        file: "knock-encoding",
        bytes_field: "encoding",
        build: |vector| {
            let subscription = match optional_bytes(vector, "subscription_id")? {
                Some(id) => Some(Subscription {
                    id: SubscriptionId::from_bytes(id),
                    push: SealedPush {
                        relay: RelayRef::Listed(RelayId::new(2)),
                        blob: SealedPushBlob::from_bytes(blob()),
                        urgency: Urgency::Quiet,
                        handle: PushHandle::from_bytes(ramp::<8>(0xf0)),
                    },
                    time_to_live: time_to_live(vector, "subscription_ttl_seconds")?,
                }),
                None => None,
            };
            Ok(Knock {
                matched_randomness: RecordRandomness::from_bytes(bytes(
                    vector,
                    "matched_randomness",
                )?),
                own_randomness: optional_bytes(vector, "own_randomness")?
                    .map(RecordRandomness::from_bytes),
                leaf_index: LeafIndex::new(small(vector, "leaf_index")?),
                party_epoch: Epoch::new(number(vector, "party_epoch")?),
                key_package: KeyPackageBytes::from_bytes(vector.input_bytes("key_package")?),
                reply_mailbox: MailboxId::from_bytes(bytes(vector, "reply_mailbox")?),
                meetup_subscription: subscription,
                signature: KnockSignature::from_bytes(bytes(vector, "signature")?),
            })
        },
        encode: Knock::encode,
        decode: Knock::decode,
    })
}

/// `start, start + 1, ...` wrapping at 256, as the generator's `ramp`.
fn ramp<const LENGTH: usize>(start: u8) -> [u8; LENGTH] {
    let mut bytes = [0; LENGTH];
    let mut next = start;
    for byte in &mut bytes {
        *byte = next;
        next = next.wrapping_add(1);
    }
    bytes
}

/// The generator's sealed push blob: `ramp(0, 256) || ramp(0, 64)`.
fn blob() -> [u8; 320] {
    let mut bytes = [0; 320];
    for (byte, value) in bytes.iter_mut().zip(ramp::<256>(0).into_iter().cycle()) {
        *byte = value;
    }
    bytes
}

